#include <bits/stdc++.h>
using namespace std;
int main() {
    int N;
    cin >> N;
    vector<string> S(N);
    for (int i = 0; i < N; i++) cin >> S[i];
    int m = 0;
    for (int i = 0; i < N; i++) m = max(m, (int)S[i].size());
    for (int i = 0; i < N; i++) {
        int k = (m - S[i].size()) / 2;
        string T = string(k, '.') + S[i] + string(k, '.');
        cout << T << "\n";
    }
}
